import { Button } from "@huspy/shared-ui";

export function InvalidIssuerPage() {
  const handleLogin = () => {
    window.huspy.auth.login({ idpHint: "google" });
  };

  return (
    <div className="flex h-screen flex-col items-center justify-center gap-4 p-6 text-center">
      <h1 className="text-2xl font-semibold text-gray-900">Account not valid</h1>
      <p className="max-w-md text-gray-500">
        This account is not valid for the new infrastructure. Please log in with a new Keycloak
        account.
      </p>
      <Button onClick={handleLogin}>Go to login</Button>
    </div>
  );
}
